"""Semantic-version comparison and range matching for the plugin registry."""

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)
_COMPARATOR_RE = re.compile(r"^(>=|<=|>|<|=|\^|~)?(.+)$")


def parse_version(text: str) -> tuple:
    """Parse 'MAJOR.MINOR.PATCH[-PRERELEASE]' into
    (major, minor, patch, prerelease_identifiers_tuple).

    Numeric parts have no leading zeros. The prerelease is a dot-separated
    list of non-empty identifiers made of [0-9A-Za-z-]. Build metadata ('+...'),
    a leading 'v', or anything else malformed raises ValueError.

    >>> parse_version("1.0.0-rc.1")
    (1, 0, 0, ('rc', '1'))
    """
    m = _VERSION_RE.match(text)
    if not m:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, pre = m.groups()
    return int(major), int(minor), int(patch), tuple(pre.split(".")) if pre else ()


def _cmp_pre(a: tuple, b: tuple) -> int:
    if a == b:
        return 0
    if not a:          # a release outranks any prerelease of the same version
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        if x == y:
            continue
        x_num, y_num = x.isdigit(), y.isdigit()
        if x_num and y_num:
            return -1 if int(x) < int(y) else 1
        if x_num != y_num:
            return -1 if x_num else 1   # numeric identifiers sort before alphanumeric
        return -1 if x < y else 1
    return -1 if len(a) < len(b) else 1


def _cmp(a: tuple, b: tuple) -> int:
    if a[:3] != b[:3]:
        return -1 if a[:3] < b[:3] else 1
    return _cmp_pre(a[3], b[3])


def compare(a: str, b: str) -> int:
    """Return -1, 0 or 1 as version `a` has lower, equal or higher precedence
    than `b`, following Semantic Versioning 2.0.0 precedence rules:
    - MAJOR, MINOR, PATCH are compared numerically, in that order;
    - a version with a prerelease has LOWER precedence than the same version
      without one (1.0.0-rc.1 < 1.0.0);
    - two prereleases are compared identifier by identifier, left to right:
      identifiers consisting only of digits are compared numerically,
      other identifiers are compared lexically in ASCII order, and a numeric
      identifier always has lower precedence than a non-numeric one;
    - if all shared identifiers are equal, the longer prerelease is higher
      (1.0.0-alpha < 1.0.0-alpha.1).
    """
    return _cmp(parse_version(a), parse_version(b))


def _upper_caret(v: tuple) -> tuple:
    major, minor, patch, _ = v
    if major > 0:
        return (major + 1, 0, 0, ())
    if minor > 0:
        return (0, minor + 1, 0, ())
    return (0, 0, patch + 1, ())


def _matches(v: tuple, comparator: str) -> bool:
    m = _COMPARATOR_RE.match(comparator)
    op, target = m.group(1) or "=", parse_version(m.group(2))
    c = _cmp(v, target)
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    if op == "~":
        return c >= 0 and _cmp(v, (target[0], target[1] + 1, 0, ())) < 0
    return c >= 0 and _cmp(v, _upper_caret(target)) < 0   # "^"


def satisfies(version: str, range_expr: str) -> bool:
    """True if `version` satisfies `range_expr`.

    A range is one or more alternatives separated by '||'; it is satisfied if
    ANY alternative is. An alternative is one or more comparators separated by
    whitespace; it is satisfied if ALL of its comparators are. A comparator is
    an optional operator immediately followed by a version:
      =V or bare V   precedence equal to V
      >V >=V <V <=V  by precedence (see `compare`)
      ~V             >=V and < MAJOR.(MINOR+1).0
      ^V             >=V and < the next version that bumps the left-most
                     non-zero part of V:
                       ^1.2.3 -> <2.0.0, ^0.2.3 -> <0.3.0, ^0.0.3 -> <0.0.4
    Bounds are compared by plain precedence (so 2.0.0-rc.1 IS below the
    exclusive bound 2.0.0 of ^1.2.3). An empty range, an empty alternative,
    or any malformed comparator/version raises ValueError.
    """
    v = parse_version(version)
    alternatives = range_expr.split("||")
    parsed = [alt.split() for alt in alternatives]
    if any(not comps for comps in parsed):
        raise ValueError(f"invalid range: {range_expr!r}")
    results = [all(_matches(v, comp) for comp in comps) for comps in parsed]
    return any(results)

