class RateLimiter:
    """Token-bucket limiter with one independent bucket per key (injected clock)."""

    def __init__(self, capacity, refill_rate, clock):
        self._validate(capacity, refill_rate)
        self.capacity = capacity
        self.refill_rate = refill_rate
        self._clock = clock
        self._buckets = {}  # key -> [tokens, last]

    @staticmethod
    def _validate(capacity, refill_rate):
        if capacity <= 0 or refill_rate <= 0:
            raise ValueError("capacity and refill_rate must be positive")

    def _check_n(self, n):
        if n <= 0 or n > self.capacity:
            raise ValueError("n must satisfy 0 < n <= capacity")

    def _refill(self, bucket, now):
        tokens, last = bucket
        if now > last:
            bucket[0] = min(self.capacity, tokens + (now - last) * self.refill_rate)
            bucket[1] = now
        return bucket

    def _touch(self, key, now):
        bucket = self._buckets.get(key)
        if bucket is None:
            bucket = self._buckets[key] = [self.capacity, now]
            return bucket
        return self._refill(bucket, now)

    def try_acquire(self, key, n=1):
        self._check_n(n)
