class OrderBook:
    """Limit order book with price-time priority and self-trade prevention."""

    SIDES = ("buy", "sell")

    def __init__(self):
        self._orders = {}                      # id -> {"side", "price", "qty", "owner"}
        self._levels = {"buy": {}, "sell": {}}  # side -> price -> [ids in priority order]
        self._used_ids = set()

    @staticmethod
    def _is_pos_int(x):
        return type(x) is int and x > 0

    def _best(self, side):
        levels = self._levels[side]
        if not levels:
            return None
        return max(levels) if side == "buy" else min(levels)

    def _remove(self, order_id):
        order = self._orders.pop(order_id)
        level = self._levels[order["side"]][order["price"]]
        level.remove(order_id)
        if not level:
            del self._levels[order["side"]][order["price"]]
        return order

    def submit(self, order_id, side, qty, price=None, owner=None):
        if order_id in self._used_ids:
            raise ValueError(f"duplicate order id {order_id!r}")
        if side not in self.SIDES:
            raise ValueError(f"invalid side {side!r}")
        if not self._is_pos_int(qty):
            raise ValueError("qty must be a positive int")
        if price is not None and not self._is_pos_int(price):
            raise ValueError("price must be a positive int or None")
        self._used_ids.add(order_id)

        opposite = "sell" if side == "buy" else "buy"
        fills = []
        remaining = qty
        while remaining > 0:
            best = self._best(opposite)
            if best is None:
                break
            if price is not None and (best > price if side == "buy" else best < price):
                break
            maker_id = self._levels[opposite][best][0]
            maker = self._orders[maker_id]
            if owner is not None and maker["owner"] == owner:
                self._remove(maker_id)
                continue
            traded = min(remaining, maker["qty"])
            fills.append((maker_id, order_id, best, traded))
            remaining -= traded
            maker["qty"] -= traded
            if maker["qty"] == 0:
                self._remove(maker_id)

        if remaining > 0 and price is not None:
            self._orders[order_id] = {"side": side, "price": price, "qty": remaining, "owner": owner}
            self._levels[side].setdefault(price, []).append(order_id)
        return fills

    def cancel(self, order_id):
        if order_id not in self._orders:
            raise KeyError(order_id)
        return self._remove(order_id)["qty"]

    def modify(self, order_id, new_qty):
        if order_id not in self._orders:
            raise KeyError(order_id)
        if not self._is_pos_int(new_qty):
            raise ValueError("new_qty must be a positive int")
        order = self._orders[order_id]
        if new_qty > order["qty"]:
            level = self._levels[order["side"]][order["price"]]
            level.remove(order_id)
            level.append(order_id)
        order["qty"] = new_qty

    def best_bid(self):
        return self._best("buy")

    def best_ask(self):
        return self._best("sell")

    def depth(self, side):
        if side not in self.SIDES:
            raise ValueError(f"invalid side {side!r}")
        levels = self._levels[side]
        prices = sorted(levels, reverse=(side == "buy"))
        return [(p, sum(self._orders[i]["qty"] for i in levels[p])) for p in prices]

    def get_order(self, order_id):
        if order_id not in self._orders:
            raise KeyError(order_id)
        o = self._orders[order_id]
        return (o["side"], o["price"], o["qty"])

