class InsufficientFunds(Exception):
    """The operation would take an account's available funds below zero."""


class HoldExpired(Exception):
    """capture/release on a hold whose expiry time has passed."""


class Ledger:
    """Accounts with balances, overdraft limits and authorization holds."""

    def __init__(self, clock):
        self._clock = clock
        self._accounts = {}   # id -> {"balance": int, "limit": int}
        self._holds = {}      # hold_id -> {"account", "amount", "expires_at"}; only open holds
        self._next_hold = 1

    @staticmethod
    def _check_amount(amount):
        if type(amount) is not int or amount <= 0:
            raise ValueError("amount must be a positive int")

    def _account(self, account_id):
        if account_id not in self._accounts:
            raise KeyError(account_id)
        return self._accounts[account_id]

    def _active_holds(self, account_id, now):
        return [(hid, h["amount"], h["expires_at"]) for hid, h in sorted(self._holds.items())
                if h["account"] == account_id and now < h["expires_at"]]

    def _available(self, account_id, now):
        acct = self._account(account_id)
        held = sum(amount for _, amount, _ in self._active_holds(account_id, now))
        return acct["balance"] + acct["limit"] - held

    def _require(self, account_id, amount, now):
        if amount > self._available(account_id, now):
            raise InsufficientFunds(account_id)

    def open_account(self, account_id, overdraft_limit=0):
        if type(overdraft_limit) is not int or overdraft_limit < 0:
            raise ValueError("overdraft_limit must be an int >= 0")
        if account_id in self._accounts:
            raise ValueError(f"account {account_id!r} already exists")
        self._accounts[account_id] = {"balance": 0, "limit": overdraft_limit}

    def deposit(self, account_id, amount):
        self._check_amount(amount)
        self._account(account_id)["balance"] += amount

    def withdraw(self, account_id, amount):
        self._check_amount(amount)
        acct = self._account(account_id)
        self._require(account_id, amount, self._clock())
        acct["balance"] -= amount

    def transfer(self, src, dst, amount):
        self._check_amount(amount)
        if src == dst:
            raise ValueError("src and dst must differ")
        source, target = self._account(src), self._account(dst)
        self._require(src, amount, self._clock())
        source["balance"] -= amount
        target["balance"] += amount

    def place_hold(self, account_id, amount, ttl):
        self._check_amount(amount)
        if isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or ttl <= 0:
            raise ValueError("ttl must be a positive number")
        self._account(account_id)
        now = self._clock()
        self._require(account_id, amount, now)
        hold_id = self._next_hold
        self._next_hold += 1
        self._holds[hold_id] = {"account": account_id, "amount": amount, "expires_at": now + ttl}
        return hold_id

    def _open_hold(self, hold_id):
        if hold_id not in self._holds:
            raise KeyError(hold_id)
        hold = self._holds[hold_id]
        if self._clock() >= hold["expires_at"]:
            raise HoldExpired(hold_id)
        return hold

    def capture(self, hold_id, amount=None):
        if amount is not None:
            self._check_amount(amount)
        hold = self._open_hold(hold_id)
        if amount is None:
            amount = hold["amount"]
        elif amount > hold["amount"]:
            raise ValueError("cannot capture more than the hold amount")
        del self._holds[hold_id]
        self._accounts[hold["account"]]["balance"] -= amount
        return amount

    def release(self, hold_id):
        self._open_hold(hold_id)
        del self._holds[hold_id]

    def balance(self, account_id):
        return self._account(account_id)["balance"]

    def available(self, account_id):
        return self._available(account_id, self._clock())

    def holds(self, account_id):
        self._account(account_id)
        return self._active_holds(account_id, self._clock())

